// The player only uses Windows source metadata. Native codecs live in the worker.
sealed class NativeRecorder : IDisposable {
 readonly Form owner;readonly bool testing;readonly string profile,data;readonly Action<object> emit;readonly Action<string> open;readonly Action requestStart;
 readonly JavaScriptSerializer json=new JavaScriptSerializer();readonly object gate=new object();readonly SemaphoreSlim writes=new SemaphoreSlim(1);
 readonly Dictionary<int,TaskCompletionSource<object>> requests=new Dictionary<int,TaskCompletionSource<object>>();
 Task warmTask;RecorderPreferences preferences;Process worker,handledExit,saveGuardWorker;RecorderProcessJob workerJob;int next,session,saveGuardSession;bool busy,disposed,compatible=true,retrying;string workerError="";Dictionary<string,object> status=new Dictionary<string,object>{{"busy",false},{"state","idle"},{"seconds",0}};
 Dictionary<string,object> region;List<RecorderSource> displays=new List<RecorderSource>();RecorderRegionFrame regionFrame;RecorderBar controlBar;Task<object> exitTask;
 public bool Busy{get{CheckWorkerExited();lock(gate)return busy;}}
 [DllImport("user32.dll")] internal static extern bool SetWindowDisplayAffinity(IntPtr window,uint affinity);
 [DllImport("user32.dll")] static extern bool GetWindowDisplayAffinity(IntPtr window,out uint affinity);
 public NativeRecorder(Form window,string userProfile,bool isTesting,Action<object> notify,Action<string> openResult,Action startFromControls=null){requestStart=startFromControls;owner=window;profile=userProfile;testing=isTesting;emit=notify;open=openResult;data=Path.Combine(profile,"recorder");Directory.CreateDirectory(data);LoadPreferences();}
 void LoadPreferences(){try{preferences=json.Deserialize<RecorderPreferences>(File.ReadAllText(Path.Combine(data,"settings.json")))??new RecorderPreferences();}catch{preferences=new RecorderPreferences();}if(testing&&Environment.GetEnvironmentVariable("YIYAN_RECORD_OUTPUT")!=null)preferences.folder=Environment.GetEnvironmentVariable("YIYAN_RECORD_OUTPUT");if(preferences.schemaVersion<2){preferences.schemaVersion=2;preferences.mode="region";preferences.preset="native";preferences.countdown=0;SavePreferences();}}
 void SavePreferences(){string path=Path.Combine(data,"settings.json");File.WriteAllText(path+".tmp",json.Serialize(preferences));if(File.Exists(path))File.Replace(path+".tmp",path,null);else File.Move(path+".tmp",path);}
 public object Config(){if(!Busy&&!disposed&&warmTask==null)warmTask=WarmWorker();LoadPreferences();displays=RecorderSources.Displays();return new{preferences=preferences,displays=displays,windows=RecorderSources.Windows(owner.Handle),outputs=RecorderSources.Audio(false),inputs=RecorderSources.Audio(true),region=region,status=Status()};}
 void CheckWorkerExited(){var process=worker;if(process!=null&&!disposed)try{if(process.HasExited)WorkerExited(process);}catch(InvalidOperationException){}}
 public Dictionary<string,object> Status(){CheckWorkerExited();lock(gate)return new Dictionary<string,object>(status);}
 public object SelectRegion(string display){if(Busy)throw new Exception("Please end current recording first");HideRegion();using(var dpi=new RecorderDpiScope())using(var picker=new RecorderRegionPicker(RecorderDesktop.Bounds())){if(picker.ShowDialog(owner)==DialogResult.OK)region=RecorderDesktop.Region(picker.Selection);}ShowRegion();return region;}
 public object ShowRegion(){if(region==null)return false;using(var dpi=new RecorderDpiScope()){var bounds=RecorderDesktop.Resolve(region,Convert.ToString(region["display"]));if(regionFrame==null||regionFrame.IsDisposed||regionFrame.SelectionBounds!=bounds){HideRegion();regionFrame=new RecorderRegionFrame(bounds);}regionFrame.Show();if(controlBar==null||controlBar.IsDisposed)controlBar=new RecorderBar(()=>ControlAction("pause"),()=>ControlAction("stop"),()=>ControlAction("exit"),()=>ControlAction("start"));var screens=RecorderDesktop.Screens();var controlArea=RecorderDesktop.ControlArea(bounds,screens);var controlSize=controlBar.FitInside(controlArea);var controlBounds=RecorderDesktop.ControlBounds(controlArea,controlSize,screens);controlBar.Place(controlBounds);controlBar.Show();controlBar.Place(controlBounds);SetWindowDisplayAffinity(controlBar.Handle,0x11);SyncControls();return true;}}
 public object HideRegion(){if(controlBar!=null){controlBar.Dispose();controlBar=null;}if(regionFrame!=null){regionFrame.Dispose();regionFrame=null;}return true;}
 void SyncControls(){if(controlBar==null||controlBar.IsDisposed)return;var value=Status();bool active=value.ContainsKey("busy")&&Convert.ToBoolean(value["busy"]),paused=value.ContainsKey("paused")&&Convert.ToBoolean(value["paused"]);string state=value.ContainsKey("state")?Convert.ToString(value["state"]):"idle";double seconds=value.ContainsKey("seconds")?Convert.ToDouble(value["seconds"]):0;controlBar.UpdatePhase(TimeSpan.FromSeconds(seconds),active,paused,state);}
 async void ControlAction(string action){try{if(action=="start"){if(!Busy&&region!=null&&requestStart!=null)requestStart();return;}if(action=="exit")await Exit();else if(action=="pause")await Pause();else await Stop();SyncControls();}catch(Exception e){SyncControls();var value=Status();value["error"]=e.Message;emit(value);}}
 public Task<object> Exit(){if(exitTask!=null&&!exitTask.IsCompleted)return exitTask;return exitTask=ExitCore();}
 async Task<object> ExitCore(){region=null;HideRegion();var value=Status();value["dismissed"]=true;emit(value);if(Busy)await Stop();return Status();}
 public object TestRegion(string display){if(!testing||Busy)throw new Exception("Available only for testing");region=new Dictionary<string,object>{{"x",0},{"y",0},{"width",640},{"height",360},{"display",display}};return region;}
 public object ChooseFolder(){if(Busy)throw new Exception("After recording ends, you can change save location");LoadPreferences();string selected=NativeFolderPicker.Show(owner,"Where is the video saved?",preferences.folder);if(selected!=null){preferences.folder=selected;SavePreferences();}return new{folder=preferences.folder};}
 public Task<object> OpenFolder(){LoadPreferences();Directory.CreateDirectory(preferences.folder);return NativeShell.Reveal(preferences.folder,testing);}
 public Task<object> RevealLast(){string file,recovery;lock(gate){file=status.ContainsKey("path")?Convert.ToString(status["path"]):null;recovery=status.ContainsKey("recoveryFolder")?Convert.ToString(status["recoveryFolder"]):null;}if(!string.IsNullOrEmpty(recovery)&&Directory.Exists(recovery)){return NativeShell.Reveal(recovery,testing);}if(string.IsNullOrEmpty(file)||!File.Exists(file))return OpenFolder();return NativeShell.Reveal(file,testing);}
 public object FrameStatus(){uint playerAffinity,frameAffinity=0,controlAffinity=0;bool playerQueried=GetWindowDisplayAffinity(owner.Handle,out playerAffinity),frameVisible=regionFrame!=null&&!regionFrame.IsDisposed&&regionFrame.Visible,frameQueried=frameVisible&&GetWindowDisplayAffinity(regionFrame.Handle,out frameAffinity),controlsVisible=controlBar!=null&&!controlBar.IsDisposed&&controlBar.Visible,controlsQueried=controlsVisible&&GetWindowDisplayAffinity(controlBar.Handle,out controlAffinity);var bounds=regionFrame==null?Rectangle.Empty:regionFrame.SelectionBounds;return new{visible=frameVisible,bounds=regionFrame==null?null:(object)new{x=bounds.X,y=bounds.Y,width=bounds.Width,height=bounds.Height},playerCaptureAllowed=playerQueried&&playerAffinity==0,frameCaptureAllowed=frameQueried&&frameAffinity==0,controlsVisible=controlsVisible,controlState=controlsVisible?controlBar.ControlState():null,controlsExcludedFromCapture=controlsQueried&&controlAffinity==0x11,controlBounds=controlsVisible?(object)new{x=controlBar.Left,y=controlBar.Top,width=controlBar.Width,height=controlBar.Height}:null};}
 public object TestDesktopRegion(Dictionary<string,object> box){if(!testing||Busy)throw new Exception("Available only for testing");region=RecorderDesktop.Region(new Rectangle(Convert.ToInt32(box["x"]),Convert.ToInt32(box["y"]),Convert.ToInt32(box["width"]),Convert.ToInt32(box["height"])));return ShowRegion();}
 public object TestControl(string action){if(!testing)throw new Exception("Available only for testing");if(controlBar==null||controlBar.IsDisposed)throw new Exception("Screen recording control bar is unavailable");if(action=="snapshot"){string file=Path.Combine(data,"control-preview.png");controlBar.SavePreview(file);return new{path=file};}if(action=="move"){controlBar.Left-=40;controlBar.Top-=40;return true;}controlBar.ClickForTest(action);return true;}

 async Task EnsureWorker(){if(disposed)throw new ObjectDisposedException("Recorder");if(worker!=null&&!worker.HasExited)return;workerError="";string core=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Xiaoma Player Core.exe");var start=new ProcessStartInfo(File.Exists(core)?core:Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Xiaoma Player.exe"),"--recorder-worker "+NativeExporter.Quote(profile)+" "+(testing?"1":"0")+" "+Process.GetCurrentProcess().Id){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=System.Text.Encoding.UTF8,StandardErrorEncoding=System.Text.Encoding.UTF8};
  if(compatible)start.Arguments=start.Arguments.Replace("--recorder-worker","--recorder-compat");var process=new Process{StartInfo=start,EnableRaisingEvents=true};process.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)lock(gate)workerError=(workerError+e.Data+"\n");};process.Exited+=(s,e)=>WorkerExited(process);worker=process;if(!process.Start())throw new Exception("Screen recording component failed to start");workerJob=RecorderProcessJob.Attach(process);process.BeginErrorReadLine();_ = ReadResponses(process);await Task.Yield();
 }
 async Task ReadResponses(Process process){try{string line;while((line=await process.StandardOutput.ReadLineAsync())!=null){if(process!=worker||process.HasExited||line.Length>1024*1024)continue;Dictionary<string,object> message;try{message=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(line);}catch{continue;}object id;
    if(message.TryGetValue("id",out id)){TaskCompletionSource<object> completion;lock(gate){if(!requests.TryGetValue(Convert.ToInt32(id),out completion))continue;requests.Remove(Convert.ToInt32(id));}object error;if(message.TryGetValue("error",out error))completion.TrySetException(new Exception(Convert.ToString(error)));else completion.TrySetResult(message.ContainsKey("result")?message["result"]:null);}
    else if(message.ContainsKey("status")){var update=(Dictionary<string,object>)message["status"];if(update.ContainsKey("session")&&Convert.ToInt32(update["session"])!=session)continue;lock(gate){if(process!=worker||process.HasExited)continue;foreach(var item in update)status[item.Key]=item.Value;busy=status.ContainsKey("busy")&&Convert.ToBoolean(status["busy"]);}WatchSaving(process,update);OnUi(()=>{if(process!=worker||process.HasExited||retrying&&Convert.ToString(update["state"])=="failed")return;if(!Busy)SetWindowDisplayAffinity(owner.Handle,0);if(Convert.ToString(update["state"])=="failed"&&!testing){owner.WindowState=FormWindowState.Normal;owner.Show();}SyncControls();emit(update);});}
    else if(message.ContainsKey("open")){string path=Convert.ToString(message["open"]);OnUi(()=>{if(!disposed){owner.WindowState=FormWindowState.Normal;owner.Show();open(path);}});}
   }}catch(Exception e){lock(gate)workerError+=e.Message;}
 }
 void WorkerExited(Process process){if(process!=worker||disposed)return;string message="Screen recording component encountered an error, please retry. Playback can still be used.";List<TaskCompletionSource<object>> pending;RecorderProcessJob exitedJob;bool active;lock(gate){if(handledExit==process)return;handledExit=process;exitedJob=workerJob;workerJob=null;pending=requests.Values.ToList();requests.Clear();active=busy;busy=false;if(active){status["busy"]=false;status["state"]="failed";status["error"]=message;}}
  if(exitedJob!=null)exitedJob.Dispose();
  if(active&&!disposed){try{File.AppendAllText(Path.Combine(data,"worker-errors.log"),DateTime.Now.ToString("o")+" exit="+process.ExitCode+" "+workerError+Environment.NewLine);}catch{}OnUi(()=>{if(process!=worker||retrying)return;SetWindowDisplayAffinity(owner.Handle,0);owner.WindowState=FormWindowState.Normal;owner.Show();SyncControls();emit(Status());});}
  foreach(var completion in pending)completion.TrySetException(new Exception(message));
 }
 async Task<object> Call(string method,object args=null,int timeout=60000){await EnsureWorker();int id;var completion=new TaskCompletionSource<object>(TaskCreationOptions.RunContinuationsAsynchronously);lock(gate){id=++next;requests[id]=completion;}
  try{await writes.WaitAsync();try{await worker.StandardInput.WriteLineAsync(json.Serialize(new{id=id,method=method,args=args}));await worker.StandardInput.FlushAsync();}finally{writes.Release();}if(await Task.WhenAny(completion.Task,Task.Delay(timeout))!=completion.Task)throw new Exception("Screen recording component response timeout, please end current operation and retry");return await completion.Task;}
  finally{lock(gate)requests.Remove(id);}
 }
 async Task CloseWorker(Process process){RecorderProcessJob job=null;lock(gate){if(worker==process){worker=null;job=workerJob;workerJob=null;}}if(job!=null)job.Dispose();if(process!=null)await Task.Run(()=>{try{process.StandardInput.Close();if(!process.WaitForExit(1000))process.Kill();process.Dispose();}catch{}});}
 void WatchSaving(Process process,Dictionary<string,object> update){object value;if(!update.TryGetValue("state",out value)||Convert.ToString(value)!="saving")return;int current=session;if(saveGuardWorker==process&&saveGuardSession==current)return;saveGuardWorker=process;saveGuardSession=current;int timeout=update.ContainsKey("saveTimeoutMs")?Convert.ToInt32(update["saveTimeoutMs"]):30000;_ = GuardSaving(process,current,Math.Max(1000,Math.Min(600000,timeout))+2000);}
 async Task GuardSaving(Process process,int current,int timeout){await Task.Delay(timeout);List<TaskCompletionSource<object>> pending;string message="Recording save did not complete in time, pending recovery file has been retained. You can retry recording.";lock(gate){if(disposed||process!=worker||session!=current||!busy||Convert.ToString(status["state"])!="saving")return;busy=false;status["busy"]=false;status["state"]="failed";status["error"]=message;pending=requests.Values.ToList();requests.Clear();}await CloseWorker(process);foreach(var completion in pending)completion.TrySetException(new Exception(message));OnUi(()=>{SetWindowDisplayAffinity(owner.Handle,0);owner.WindowState=FormWindowState.Normal;SyncControls();emit(Status());});}
 async Task WarmWorker(){try{await Call("prepare",null,15000);}catch{if(disposed||busy)return;var old=worker;compatible=true;await CloseWorker(old);try{if(!disposed)await Call("prepare",null,15000);}catch{}}}
 public async Task<object> Start(Dictionary<string,object> args){if(warmTask!=null)await warmTask;if(Busy)throw new Exception("Recording or saving, please wait");if(Convert.ToString(status["state"])=="failed"){await CloseWorker(worker);warmTask=null;}session++;args["session"]=session;args["countdown"]=0;args["controllerControls"]=true;if(args.ContainsKey("mode")&&Convert.ToString(args["mode"])=="region"){if(region==null)throw new Exception("Please first select a region");args["region"]=region;args["display"]=region["display"];ShowRegion();}
  lock(gate){busy=true;status["busy"]=true;status["state"]="preparing";}SetWindowDisplayAffinity(owner.Handle,0);SyncControls();emit(Status());
  try{object result;retrying=!compatible;try{result=await Call("start",args);}catch(Exception first){if(compatible)throw;File.AppendAllText(Path.Combine(data,"worker-errors.log"),DateTime.Now.ToString("o")+" switching to compatible capture: "+first+Environment.NewLine);var old=worker;await CloseWorker(old);compatible=true;retrying=false;lock(gate){busy=true;status["busy"]=true;status["state"]="preparing";}emit(Status());result=await Call("start",args);}retrying=false;if(Busy&&!testing&&args.ContainsKey("minimize")&&Convert.ToBoolean(args["minimize"]))owner.WindowState=FormWindowState.Minimized;SyncControls();return result;}
  catch{retrying=false;lock(gate){busy=false;status["busy"]=false;status["state"]="idle";}SetWindowDisplayAffinity(owner.Handle,0);SyncControls();emit(Status());throw;}
 }
 public async Task<object> Pause(){if(!Busy)return Status();return await Call("pause");}
 public async Task<object> Stop(){if(!Busy)return Status();lock(gate){if(Convert.ToString(status["state"])!="preparing")status["state"]="saving";}SyncControls();emit(Status());return await Call("stop",null,660000);}
 void OnUi(Action action){if(owner.IsDisposed)return;try{if(owner.InvokeRequired)owner.BeginInvoke(action);else action();}catch{}}
 public int WorkerProcessId{get{return worker!=null&&!worker.HasExited?worker.Id:0;}}
 public void Dispose(){disposed=true;HideRegion();if(workerJob!=null){workerJob.Dispose();workerJob=null;}var process=worker;if(process!=null){try{process.StandardInput.Close();if(!process.WaitForExit(2000))process.Kill();}catch{}process.Dispose();}SetWindowDisplayAffinity(owner.Handle,0);}
}

static class RecorderSources {
 delegate bool EnumWindowCallback(IntPtr window,IntPtr parameter);
 [DllImport("user32.dll")]static extern bool EnumWindows(EnumWindowCallback callback,IntPtr parameter);
 [DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr window);
 [DllImport("user32.dll")]static extern IntPtr GetAncestor(IntPtr window,uint flag);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr window,out uint pid);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr window,System.Text.StringBuilder text,int maximum);
 [DllImport("gdi32.dll",CharSet=CharSet.Unicode)]static extern IntPtr CreateDC(string driver,string device,string output,IntPtr mode);
 [DllImport("gdi32.dll")]static extern int GetDeviceCaps(IntPtr dc,int index);
 [DllImport("gdi32.dll")]static extern bool DeleteDC(IntPtr dc);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern bool EnumDisplaySettings(string device,int mode,IntPtr settings);
 public static Point PhysicalOrigin(string device){IntPtr buffer=Marshal.AllocHGlobal(220);try{for(int i=0;i<220;i++)Marshal.WriteByte(buffer,i,0);Marshal.WriteInt16(buffer,68,220);if(EnumDisplaySettings(device,-1,buffer))return new Point(Marshal.ReadInt32(buffer,76),Marshal.ReadInt32(buffer,80));var screen=Screen.AllScreens.First(s=>s.DeviceName==device);return screen.Bounds.Location;}finally{Marshal.FreeHGlobal(buffer);}}
 public static List<RecorderSource> Displays(){return Screen.AllScreens.OrderByDescending(s=>s.Primary).Select((s,i)=>{int w=s.Bounds.Width,h=s.Bounds.Height;IntPtr dc=CreateDC("DISPLAY",s.DeviceName,null,IntPtr.Zero);try{if(dc!=IntPtr.Zero){w=GetDeviceCaps(dc,118);h=GetDeviceCaps(dc,117);}}finally{if(dc!=IntPtr.Zero)DeleteDC(dc);}return new RecorderSource{id=s.DeviceName,device=s.DeviceName,name="Screen "+(i+1)+(s.Primary?" (Main screen)":"")+" · "+w+"×"+h,width=w,height=h,primary=s.Primary};}).ToList();}
 public static List<RecorderSource> Windows(IntPtr owner){var result=new List<RecorderSource>();EnumWindows((window,_)=>{try{if(window==owner||!IsWindowVisible(window)||GetAncestor(window,2)!=window)return true;uint pid;GetWindowThreadProcessId(window,out pid);if(pid==Process.GetCurrentProcess().Id)return true;var text=new System.Text.StringBuilder(512);GetWindowText(window,text,text.Capacity);string title=text.ToString();if(!string.IsNullOrWhiteSpace(title))result.Add(new RecorderSource{id=window.ToInt64().ToString(),handle=window.ToInt64(),name=title});}catch{}return true;},IntPtr.Zero);return result;}
 public static object[] Audio(bool input){try{return RecorderAudioDevices.List(input);}catch{return new object[0];}}
}
